@Component("taxWithholding-subscriber")
public class TaxWithholdingSubscriber extends BaseSubscriber {

	public TaxWithholdingSubscriber() {
	}
	
    public SubscriptionQueryResult<List<TaxWithholding>, TaxWithholding> taxWithholdingSubscribe() {
        return queryGateway
                .subscriptionQuery(new FindAllTaxWithholdingQuery(), 
                		ResponseTypes.multipleInstancesOf(TaxWithholding.class),
                		ResponseTypes.instanceOf(TaxWithholding.class));
    }

    public SubscriptionQueryResult<TaxWithholding, TaxWithholding> taxWithholdingSubscribe(@DestinationVariable UUID taxWithholdingId) {
        return queryGateway
                .subscriptionQuery(new FindTaxWithholdingQuery(new LoadTaxWithholdingFilter(taxWithholdingId)), 
                		ResponseTypes.instanceOf(TaxWithholding.class),
                		ResponseTypes.instanceOf(TaxWithholding.class));
    }





}

